INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('33a5cd17-6452-48e7-bf0c-4fa2c0c80027', 'f7b5c1e8-ebc8-48ed-a395-55f75f066757', 'A 55-year-old male with recurrent gout attacks (3 flares in the last 6 months) has had his acute flare resolve. Serum urate is 480 micromol/L. eGFR is normal. (Case Ref: MUSCULOSKELETAL-1231). Relevant physiological and medication history have been reviewed.', 'What is the recommended approach for starting Urate Lowering Therapy (ULT)?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('62b3db6f-ee3d-4e5a-9ecc-8cf7a6a3f3c4', 'f7b5c1e8-ebc8-48ed-a395-55f75f066757', 'A', 'Initiate Allopurinol 100 mg daily with concurrent Colchicine 500 mcg od-bd as flare prophylaxis for up to 6 months; titrate monthly to urate < 300 micromol/L', 1, 'Correct. NICE NG219 recommends a treat-to-target strategy with target urate < 300 micromol/L. Prophylactic colchicine or NSAID prevents mobilization flares.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c58ae5a2-f568-4b84-995e-dbb131ea3d21', 'f7b5c1e8-ebc8-48ed-a395-55f75f066757', 'B', 'Start Allopurinol 300 mg daily without flare prophylaxis cover', 0, 'Sub-optimal. Rapid unbuffered drop in serum urate triggers acute crystal shedding and severe flare, leading to patient non-adherence.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('04b8b9f9-9de6-4d1f-93de-e4185b696640', 'f7b5c1e8-ebc8-48ed-a395-55f75f066757', 'C', 'Prescribe Colchicine in a patient taking strong P-gp / CYP3A4 inhibitors (e.g. Clarithromycin) with severe renal failure', 0, 'Fatal toxicity risk. Severe neuro-myopathy and bone marrow suppression occur rapidly.', 2, 1789734485);
