INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('850ebb43-dd80-47dd-a155-b50baef41e65', 'ACP-Q-1321', 1, 'published', 'p-mpharm', 'sub-eczema', 'hard', 'sba', 'gp', 'human', 1789734485, 1789734485, 1789734485);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('1b0e4c2f-366a-40a2-b36d-f460949ae34c', '850ebb43-dd80-47dd-a155-b50baef41e65', 'A mother asks for advice regarding her 4-year-old child who has a severe atopic eczema flare on the face and flexural folds. She has tubes of Clobetasol propionate, Betamethasone valerate, and Hydrocortisone 1%. (Case Ref: DERMATOLOGY-1321). Relevant physiological and medication history have been reviewed.', 'Which topical steroid is safe and appropriate for short-term application to the facial flare?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ef5042e1-604d-4763-9cbf-40ce13c21ff0', '850ebb43-dd80-47dd-a155-b50baef41e65', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c70ee30b-13e3-424d-b9db-ee51ddebbaf3', '850ebb43-dd80-47dd-a155-b50baef41e65', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('594be9de-2d22-4e26-b738-49c6cda1dd1f', '850ebb43-dd80-47dd-a155-b50baef41e65', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('bfd4bb49-9677-485e-a8df-7195e9e84086', '850ebb43-dd80-47dd-a155-b50baef41e65', 'D', 'Mix topical steroid 50:50 with liquid paraffin in the dispensing tub', 0, 'Deprecated historical practice. Diluting steroids leads to unpredictable stability and microbial contamination.', 3, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('97afdcf5-b187-47d5-b851-3f272f81cae2', '850ebb43-dd80-47dd-a155-b50baef41e65', 'E', 'Apply emollient simultaneously without leaving a 20-30 minute interval', 0, 'Incorrect technique. Applying emollient at the exact same moment dilutes the active steroid and spreads it to unaffected skin.', 4, 1789734485);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('1aba6d31-b468-491c-864a-09b3efb74a68', '850ebb43-dd80-47dd-a155-b50baef41e65', 'Use mild corticosteroids (Hydrocortisone 1%) for face and flexures. Allow 20-30 minutes between steroid and emollient.', 'One Fingertip Unit (FTU) is approximately 0.5 g and covers the area of two adult palms. Reference: NICE CG57 & BNF Chapter 13.', 'NICE CG57 & BNF Chapter 13', 1789734485, 1789734485);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('866e131a-b909-41a3-90fe-9808642b5a6a', '850ebb43-dd80-47dd-a155-b50baef41e65', 1789734485, 1789734485, 1789734485, 1789734485, 0, 1789734485, 1789734485);
