INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('15ca700f-6880-41ee-88ef-9e613a0f651e', 'b66b55ae-be5d-48af-8f4e-1ebaeb39cd2d', 'A mother asks for advice regarding her 4-year-old child who has a severe atopic eczema flare on the face and flexural folds. She has tubes of Clobetasol propionate, Betamethasone valerate, and Hydrocortisone 1%. (Case Ref: DERMATOLOGY-1400). Relevant physiological and medication history have been reviewed.', 'Which topical steroid is safe and appropriate for short-term application to the facial flare?', NULL, NULL, NULL, NULL, 1, NULL, 1789734485, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('069a41c1-2f85-4f1a-a4db-b9168dc46a56', 'b66b55ae-be5d-48af-8f4e-1ebaeb39cd2d', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('43ef584e-f45b-48a4-a6a6-0f91bce3b756', 'b66b55ae-be5d-48af-8f4e-1ebaeb39cd2d', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789734485);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0cb5fbc2-1841-4b9f-8e15-79e7c1f0046e', 'b66b55ae-be5d-48af-8f4e-1ebaeb39cd2d', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789734485);
